// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let colors = ["#0CA5B0", "#4E3F30", "#FEFEEB", "#F8F4E4", "#A5B3AA"];

let n, m;
let prev, curr, vec, vec2;
let s, t;
let mult = 0.8;
float[][][] pins;

function setup() {
  createCanvas(600, 600);
  noFill();
  noLoop();
  init();
}

function init() {
  n = int(random(4, 8));
  s = width/(n+1);
}

function draw() {
  background("#212121");
  strokeWeight(0.7);
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
      spider((i+1)*s, (j+1)*s, s*mult);
    }
  }
}

function spider(x, y, size) {
  pushMatrix();
  translate(x-size/2, y-size/2);
  rect(0, 0, size, size);
  m = 3;
  pins = new Array(4)[m][2];
  t = size/(m+1);

  for (i = 0; i < m; i++) {
    pins[0][i][0] = (i+1)*t;
    pins[0][i][1] = 0;
    pins[1][i][0] = size;
    pins[1][i][1] = (i+1)*t;
    pins[2][i][0] = (i+1)*t;
    pins[2][i][1] = size;
    pins[3][i][0] = 0;
    pins[3][i][1] = (i+1)*t;
  }
  prev = 1;
  vec = int(random(m));

  let r = 5;
  stroke(colors[int(random(colors.length))]);
  for (i = 0; i < m; i++) {
    ellipse(pins[0][i][0], pins[0][i][1], r, r);
    ellipse(pins[1][i][0], pins[1][i][1], r, r);
    ellipse(pins[2][i][0], pins[2][i][1], r, r);
    ellipse(pins[3][i][0], pins[3][i][1], r, r);
  }

  for (i = 1; i < 30; i++) {
    curr = int(random(4));
    while (prev == curr) {
       curr = int(random(4));
    }
    vec2 = int(random(m));  
    stroke(colors[int(random(colors.length))]);
    line(pins[prev][vec][0], pins[prev][vec][1], pins[curr][vec2][0], pins[curr][vec2][1]);
    vec = vec2;
    prev = curr;
  }
  popMatrix();
}

function mouseReleased() {
  init();
  redraw();
}

